// ---------------------------------------------------------------------------
// ST-01 (IT-01) — Lifecycle state badge
// ---------------------------------------------------------------------------

// ST-19 (BLG-SPEC-202, v9.17): PROFITABLE and EXIT ZONE tooltips state no R multiple
// (RISK-05 option (b); strategy_rules.md defines none). Design record §7.
const LIFECYCLE_CONFIG = {
  GRACE:      { label: "GRACE",      bg: "bg-blue-600",   tip: `The stop is tracked but not enforced until the grace period ends (${GRACE_PERIOD_DAYS} calendar days, §6).` },
  LOSING:     { label: "LOSING",     bg: "bg-red-600",    tip: "Past grace with P&L at or below zero: wide stop (§7.2). Becomes PROFITABLE when the price rises above entry." },
  PROFITABLE: { label: "PROFITABLE", bg: "bg-green-700",  tip: "Advances to Exit Zone when the price is well above the initial risk taken. The app's lifecycle labels mark this; it is not a strategy rule." },
  "EXIT ZONE":{ label: "EXIT ZONE",  bg: "bg-violet-600", tip: "The price is well above the initial risk taken. Review the stop or exit." },
  UNKNOWN:    { label: "UNKNOWN",    bg: "bg-gray-500",   tip: "No lifecycle state is available for this position." },
};

// ST-12 (BLG-FE-196, v9.10): UNKNOWN tooltip by the backend's lifecycle_reason
// (positions.md §Grace Precedence and UNKNOWN Reasons). ST-11 (v9.10) removed
// flat_after_grace: post-grace states follow strategy_rules.md §9's P&L sign.
const UNKNOWN_REASON_TIPS = {
  missing_data: "No lifecycle state: price or entry data is missing for this position.",
};

function LifecycleBadge({ state, daysInState, graceDaysRemaining, lifecycleReason }) {
  const cfg = LIFECYCLE_CONFIG[state] || LIFECYCLE_CONFIG.UNKNOWN;
  // ST-12: GRACE shows calendar days of grace left, not days in state.
  const hasGraceDays = state === "GRACE" && graceDaysRemaining != null;
  const label = hasGraceDays ? `GRACE — ${graceDaysRemaining}d left` : cfg.label;
  let tip = cfg.tip;
  let ariaLabel = `Position state: ${state}${daysInState != null ? `, ${daysInState} days in state` : ""}`;
  if (state === "GRACE") {
    tip = hasGraceDays
      ? `Grace period: ${graceDaysRemaining} calendar day${graceDaysRemaining !== 1 ? "s" : ""} left. ${cfg.tip}`
      : `Grace period. ${cfg.tip}`;
    ariaLabel = hasGraceDays
      ? `Position state: GRACE, ${graceDaysRemaining} calendar days of grace left`
      : "Position state: GRACE";
  } else if (!LIFECYCLE_CONFIG[state] || state === "UNKNOWN") {
    tip = UNKNOWN_REASON_TIPS[lifecycleReason] || LIFECYCLE_CONFIG.UNKNOWN.tip;
  }
  return (
    <span
      data-testid="lifecycle-badge"
      className={cn("inline-flex items-center px-2 py-0.5 rounded-full text-xs font-semibold text-white whitespace-nowrap", cfg.bg)}
      title={tip}
      aria-label={ariaLabel}
    >
      {label}
    </span>
  );
}

// ---------------------------------------------------------------------------
// Grace period alerts (trade plan summary per in-grace position)
// ST-04 (BLG-FE-257, v9.17): the per-position grace detail is GracePeriodView
// (src/components/positions/GracePeriodView.js). The alert cards and their
// grace_alert_dismissed_* session keys are gone.
// ---------------------------------------------------------------------------

// ST-03 (BLG-FE-262, v9.17): the warning strip runs this query, so the alerts
// are loaded before the grace entry is opened and can activate the entry when
// GET /positions is slow or fails.
function useGracePeriodAlerts() {
  const { data = [], isLoading } = useQuery({
    queryKey: ["gracePeriodAlerts"],
    queryFn: async () => {
      const res = await apiFetch(`${API_BASE}/positions/grace-period-alerts`);
      const json = await res.json();
      return json.data || [];
    },
    staleTime: 60000,
  });
  return { alerts: data, isLoading };
}

// ---------------------------------------------------------------------------
// ST-03 (IT-03) — Trail Stop modal
// ST-10 (BLG-BE-159, v9.12): read-only. The Strategy Rules & System Intent Owner
// ruled (ESC-EXEC-20261013-06, Branch B) that a user may not set or raise a stop
// manually, so the modal compares the stored stop with the ATR trail and offers no
// apply action. It never proposes a lower stop (strategy_rules.md §7.3).
// Spec: positions.md v2.18 §Trail Stop Action.
// ---------------------------------------------------------------------------

function TrailStopModal({ position, onClose }) {
  const isEligible = position?.lifecycle_state === "PROFITABLE" || position?.lifecycle_state === "EXIT ZONE";
  const hasStop = position?.current_stop != null || position?.stop_price_native != null || position?.stop_price != null;
  // ST-02 (BLG-BE-103, v8.9): fallback before trailData loads — stop_price_native matches
  // currencySymbol (native); stop_price is GBP-converted and was the wrong basis here too.
  const stopValue = position?.current_stop ?? position?.stop_price_native ?? position?.stop_price;

  const modalCurrency = currencyForMarket(position?.market);

  const { data: trailData, isLoading, isError } = useQuery({
    queryKey: ["stopTrail", position?.id],
    queryFn: async () => {
      const res = await apiFetch(`${API_BASE}/positions/${position.id}/stop-trail`);
      if (!res.ok) throw new Error("Trail calculation failed");
      const json = await res.json();
      return json.data || json;
    },
    enabled: !!position?.id && isEligible && hasStop,
  });

  useEffect(() => {
    const onKeyDown = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [onClose]);

  const atrTrailStop = trailData?.atr_trail_stop;
  const trailDiff = trailData?.trail_difference;
  const trailR = trailData?.trail_r_terms;
  const isNegativeDiff = trailDiff != null && trailDiff < 0;
  const noRaise = trailDiff != null && trailDiff <= 0;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60" role="dialog" aria-modal="true" aria-labelledby="trail-stop-modal-title">
      <div className="w-full max-w-md rounded-2xl bg-slate-900 border border-slate-700 p-6 space-y-4 mx-4">
        <div className="flex items-center justify-between">
          <div>
            {/* ST-17 (BLG-FE-218, v9.15): read-only wording per positions.md v2.22 §Trail Stop Action */}
            <h2 id="trail-stop-modal-title" className="text-lg font-semibold text-white">View Trail — {position?.ticker}</h2>
            <p className="text-xs text-slate-600 dark:text-slate-400">ATR-based stop trail calculation</p>
          </div>
          <button onClick={onClose} aria-label="Close" className="text-slate-600 dark:text-slate-400 hover:text-white"><X className="w-5 h-5" /></button>
        </div>

        {isLoading && (
          <div className="space-y-3 animate-pulse">
            <div className="h-5 bg-slate-700 rounded w-3/4" />
            <div className="h-5 bg-slate-700 rounded w-2/3" />
            <div className="h-5 bg-slate-700 rounded w-1/2" />
          </div>
        )}

        {isError && (
          <div className="text-sm text-rose-400">Unable to load trail calculation. Please try again.</div>
        )}

        {!isLoading && !isError && trailData && (
          <dl className="space-y-2 text-sm">
            <div className="flex justify-between">
              <dt className="text-slate-600 dark:text-slate-400">Current Stop</dt>
              <dd className="text-white font-medium">{formatCurrency(trailData.current_stop ?? stopValue ?? 0, { currency: modalCurrency })}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-600 dark:text-slate-400">ATR Trail Stop</dt>
              <dd className="text-white font-medium">{formatCurrency(atrTrailStop, { currency: modalCurrency })}</dd>
            </div>
            {trailDiff != null && (
              <div className="flex justify-between">
                <dt className="text-slate-600 dark:text-slate-400">Difference vs current stop</dt>
                <dd className={cn("font-medium", isNegativeDiff ? "text-amber-700 dark:text-amber-400" : "text-emerald-400")}>
                  {formatCurrency(trailDiff, { currency: modalCurrency, signed: true })}
                  {trailR != null && <span className="text-slate-600 dark:text-slate-400 ml-1">({formatR(trailR)})</span>}
                </dd>
              </div>
            )}
          </dl>
        )}

        {!isLoading && !isError && trailData && (
          <div className="space-y-2">
            <p className="text-xs text-slate-600 dark:text-slate-400">
              {/* ST-06 (BLG-BE-173, v9.15): no literal multiplier; the value is the §7.2 stop with the breakeven floor */}
              ATR trail stop = current price − (profit multiplier × {ATR_PERIOD_DAYS}-day ATR), never below your entry price. This is the strategy's profitable-position stop (§7.2).
            </p>
            {noRaise && (
              <p data-testid="trail-stop-no-raise-note" className="text-xs text-slate-600 dark:text-slate-400">
                The ATR trail stop is at or below your current stop. Stops never move down (§7.3), so there is nothing to apply.
              </p>
            )}
            <p data-testid="trail-stop-readonly-note" className="text-xs text-slate-600 dark:text-slate-400">
              The system updates stops automatically when positions load and each night. This view is for reference only.
            </p>
          </div>
        )}

        <div className="flex justify-end pt-2">
          <Button variant="outline" onClick={onClose}>
            Close
          </Button>
        </div>
      </div>
    </div>
  );
}

